    //Driver Code Starts
#include <iostream>
#include <vector>
#include <algorithm>

using namespace std;
//Driver Code Ends


int maxProfit(vector<int>& arr) {

    int n = arr.size();

    vector<vector<int>> dp(n + 2, vector<int>(2, 0));

    for (int i = n - 1; i >= 0; i--) {

        // When we can buy
        dp[i][1] = max(-arr[i] + dp[i + 1][0], dp[i + 1][1]);

        // When we can sell
        dp[i][0] = max(arr[i] + dp[i + 2][1], dp[i + 1][0]);
    }

    return dp[0][1];
}


